def verify_isbn(isbn: str) -> str:
    # Check if the input is a string
    if not isinstance(isbn, str):
        raise TypeError("isbn must be a string")

    # Check if the input is in the correct format
    if not isbn.isdigit():
        raise ValueError("isbn must be a string of digits")
    if len(isbn) != 13:
        raise ValueError("isbn must be 13 characters long")
    if isbn[-1] not in ["X", "x"]:
        raise ValueError("isbn must end with 'X' or 'x'")

    # Calculate the checksum
    checksum = 0
    for i, d in enumerate(isbn[:-1]):
        checksum += int(d) * (i % 2 + 1)
    checksum = (checksum % 11) % 10

    # Check if the checksum is correct
    if isbn[-1].lower() == chr(ord("a") + checksum):
        return "Right"
    else:
        # If the checksum is incorrect, return the corrected isbn
        return f"{isbn[:-1]}{chr(ord('a') + checksum)}"
```
