def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize the dp table with 0 for all indices
    dp = [0] * (T + 1)

    # Loop through each herb and its time and value
    for time, value in herbs:
        # Loop through each time step
        for i in range(T, -1, -1):
            # Check if the current time step is greater than the time required to pick the herb
            if i >= time:
                # Update the dp value for the current time step by maximum of the current value and the previous dp value plus the value of the herb
                dp[i] = max(dp[i], dp[i - time] + value)

    # Return the maximum dp value
    return max(dp)
