            if i == 0 or j == 0:
                dp[i][j] = 0
            else:
                dp[i][j] = -1

    # Initialize the results for the base case
    for i in range(n):
        dp[volumes[i]][i + 1] = volumes[i]

    # Iterate over the volumes and items
    for i in range(V):
        for j in range(n):
            # Calculate the maximum volume that can be occupied by any subset of the first j items
            max_volume = 0
            for k in range(j + 1):
                max_volume = max(max_volume, dp[i - volumes[k]][k])

            # Update the result for the current subproblem
            dp[i][j + 1] = max(dp[i][j], max_volume + volumes[j])

    # Return the minimum remaining space
    return V - dp[V][n]
