def min_remaining_space(V, n, volumes):
    # Initialize a 2D table to store the results of subproblems
    dp = [[0 for j in range(n+1)] for i in range(V+1)]

    # Fill in the table
    for i in range(1, V+1):
        for j in range(1, n+1):
            # If the current volume is greater than the item's volume, take the maximum of the options
            if i >= volumes[j-1]:
                dp[i][j] = max(dp[i-volumes[j-1]][j-1], dp[i][j-1])
            # Otherwise, the current item cannot be included
            else:
                dp[i][j] = dp[i][j-1]

    # Return the minimum remaining space
    return V - dp[V][n]
