def vigenere_decrypt(key, ciphertext):
    """Decrypts a ciphertext encrypted with the Vigenère cipher using the provided key."""
    plaintext = ""
    for i in range(len(ciphertext)):
        key_char = key[i % len(key)]
        ciphertext_char = ciphertext[i]
        if ciphertext_char in string.ascii_lowercase:
            plaintext_char = chr((ord(ciphertext_char) - ord(key_char) + 26) % 26 + ord('a'))
        elif ciphertext_char in string.ascii_uppercase:
            plaintext_char = chr((ord(ciphertext_char) - ord(key_char) + 26) % 26 + ord('A'))
        else:
            plaintext_char = ciphertext_char
        plaintext += plaintext_char
    return plaintext
